using OrbitalSim.Domain;

namespace OrbitalSim.Application.DTOs;

/// <summary>
/// A resolved scenario: bodies [0, <see cref="NamedBodyCount"/>) come from the input body list,
/// the rest are test particles generated by <see cref="ParticleGroups"/>.
/// </summary>
public sealed record BuiltScenario(
    SimulationScenario Scenario,
    int NamedBodyCount,
    IReadOnlyList<ParticleGroupInfo> ParticleGroups)
{
    public static BuiltScenario Of(SimulationScenario scenario) => new(scenario, scenario.Bodies.Count, []);

    public int ParticleCount => Scenario.Bodies.Count - NamedBodyCount;
}
